package com.alsafa.native4;import android.app.Activity;import android.content.Intent;import android.os.Bundle;public final class MoreActivity extends Activity{@Override public void onCreate(Bundle s){super.onCreate(s);setContentView(R.layout.activity_more);go(R.id.moreProducts,ProductActivity.class);go(R.id.morePurchases,PurchaseActivity.class);go(R.id.moreOnline,OnlineSaleActivity.class);go(R.id.moreQuickRepair,DirectPartSaleActivity.class);go(R.id.moreHandover,HandoverActivity.class);go(R.id.moreCash,CashActivity.class);go(R.id.moreClosing,ClosingActivity.class);go(R.id.moreReports,ReportsActivity.class);go(R.id.moreAdvisor,WatchAdvisorActivity.class);go(R.id.moreSettings,SettingsActivity.class);Nav5.bind(this,R.id.navMore);}private void go(int id,Class<?> c){findViewById(id).setOnClickListener(v->startActivity(new Intent(this,c)));}}